// Mini-Raft en un solo proceso. Nodos = objetos; red = cola con demora; todo con semilla fija.
function rng(s){return()=>{s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
class Cluster {
  constructor(n, seed, log){
    this.r=rng(seed); this.t=0; this.n=n; this.q=[]; this.cortes=new Set(); this.log=log||(()=>{});
    this.nodos=[...Array(n)].map((_,i)=>({id:i,vivo:true,estado:'seguidor',term:0,voto:null,reg:[],commit:0,
      limite:this.timeout(),votos:0,sig:[],coinc:[]}));
  }
  timeout(){return this.t+150+Math.floor(this.r()*150)}           // elección: 150-300 ticks
  enviar(de,a,m){ if(this.cortes.has(de+'>'+a)) return;           // partición: el mensaje se pierde
    this.q.push({en:this.t+1+Math.floor(this.r()*3),a,m:{...m,de}}) }
  cortar(A,B){for(const a of A)for(const b of B){this.cortes.add(a+'>'+b);this.cortes.add(b+'>'+a)}}
  sanar(){this.cortes.clear()}
  caer(i){const x=this.nodos[i];x.vivo=false;this.log(`nodo ${i} cae`)}
  volver(i){const x=this.nodos[i];x.vivo=true;x.estado='seguidor';x.limite=this.timeout();this.log(`nodo ${i} vuelve (term ${x.term}, log ${x.reg.length})`)}
  mayoria(){return Math.floor(this.n/2)+1}
  lider(){return this.nodos.filter(x=>x.vivo&&x.estado==='lider').sort((a,b)=>b.term-a.term)[0]}
  pedir(cmd,x){x=x||this.lider(); if(!x||x.estado!=='lider')return false; x.reg.push({term:x.term,cmd});this.log(`lider ${x.id} (term ${x.term}) recibe «${cmd}» en el índice ${x.reg.length}`);this.latir(x);return true}
  empezarEleccion(x){x.estado='candidato';x.term++;x.voto=x.id;x.votos=1;x.limite=this.timeout();
    this.log(`nodo ${x.id} no oye al líder: candidato en term ${x.term}`);
    const ult=x.reg.length?x.reg[x.reg.length-1].term:0;
    for(const y of this.nodos)if(y.id!==x.id)this.enviar(x.id,y.id,{k:'voto?',term:x.term,li:x.reg.length,lt:ult})}
  ser(x,term){if(term>x.term){x.term=term;x.voto=null;if(x.estado!=='seguidor')this.log(`nodo ${x.id} ve term ${term}: vuelve a seguidor`);x.estado='seguidor'}}
  latir(x){for(const y of this.nodos){if(y.id===x.id)continue;const ni=x.sig[y.id]??x.reg.length+1;
    const pi=ni-1;this.enviar(x.id,y.id,{k:'añadir',term:x.term,pi,pt:pi?x.reg[pi-1].term:0,ents:x.reg.slice(pi),commit:x.commit})}}
  recibir(x,m){
    if(m.term!==undefined)this.ser(x,m.term);
    if(m.k==='voto?'){const ult=x.reg.length?x.reg[x.reg.length-1].term:0;
      const alDia=m.lt>ult||(m.lt===ult&&m.li>=x.reg.length);
      const ok=m.term>=x.term&&(x.voto===null||x.voto===m.de)&&alDia;
      if(ok){x.voto=m.de;x.limite=this.timeout()}
      this.enviar(x.id,m.de,{k:'voto',term:x.term,ok})}
    else if(m.k==='voto'&&x.estado==='candidato'&&m.term===x.term&&m.ok){
      if(++x.votos>=this.mayoria()){x.estado='lider';x.sig=this.nodos.map(()=>x.reg.length+1);x.coinc=this.nodos.map(()=>0);x.coinc[x.id]=x.reg.length;
        this.log(`nodo ${x.id} gana con ${x.votos} votos: LÍDER del term ${x.term}`);x.prox=this.t;}}
    else if(m.k==='añadir'){
      if(m.term<x.term){this.enviar(x.id,m.de,{k:'resp',term:x.term,ok:false,fin:0});return}
      x.estado='seguidor';x.limite=this.timeout();
      const ok=m.pi===0||(x.reg.length>=m.pi&&x.reg[m.pi-1].term===m.pt);
      if(ok){let i=m.pi;for(const e of m.ents){if(x.reg[i]&&x.reg[i].term!==e.term){this.log(`nodo ${x.id} descarta ${x.reg.length-i} entrada(s) sin confirmar: «${x.reg.slice(i).map(z=>z.cmd).join(', ')}»`);x.reg.length=i}
          if(!x.reg[i])x.reg[i]=e;i++}
        if(m.commit>x.commit)x.commit=Math.min(m.commit,m.pi+m.ents.length)}
      this.enviar(x.id,m.de,{k:'resp',term:x.term,ok,fin:m.pi+m.ents.length})}
    else if(m.k==='resp'&&x.estado==='lider'&&m.term===x.term){
      if(m.ok){x.coinc[m.de]=Math.max(x.coinc[m.de],m.fin);x.sig[m.de]=x.coinc[m.de]+1;
        for(let N=x.reg.length;N>x.commit;N--){const c=x.coinc.filter((v,i)=>i!==x.id&&v>=N).length+1;
          if(c>=this.mayoria()&&x.reg[N-1].term===x.term){x.commit=N;this.log(`lider ${x.id} confirma hasta el índice ${N} («${x.reg[N-1].cmd}»)`);break}}}
      else x.sig[m.de]=Math.max(1,x.sig[m.de]-1)}
  }
  tick(){this.t++;
    const hoy=this.q.filter(e=>e.en<=this.t);this.q=this.q.filter(e=>e.en>this.t);
    for(const e of hoy){const x=this.nodos[e.a];if(x.vivo)this.recibir(x,e.m)}
    for(const x of this.nodos){if(!x.vivo)continue;
      if(x.estado==='lider'){if(this.t-x.prox>=50){x.prox=this.t;this.latir(x)}}
      else if(this.t>=x.limite)this.empezarEleccion(x)}}
  correr(k){for(let i=0;i<k;i++)this.tick()}
}

