const {Cluster}=require('./raft.js');
class Fijo extends Cluster{ timeout(){return this.t+200} }   // sin azar: todos esperan lo mismo
function primerLider(Clase){
  const T=[];
  for(let semilla=1;semilla<=200;semilla++){
    const c=new Clase(5,semilla); let t=0;
    while(!c.lider()&&t<5000){c.tick();t++}
    T.push(t);
  }
  T.sort((a,b)=>a-b);
  return {mediana:T[100],peor:T[199],sinLiderEn5000:T.filter(x=>x>=5000).length};
}
console.log('timeout al azar 150-300:',primerLider(Cluster));
console.log('timeout fijo de 200    :',primerLider(Fijo));

const {Cluster}=require('./raft.js');
let sinLider=0,term2=0,viol=0,dobles=0,cuantas=0,tiempos=[];
for(let seed=1;seed<=300;seed++){
  const c=new Cluster(5,seed); const lid={}; let n=0;
  const chequear=()=>{for(const x of c.nodos)if(x.estado==='lider'){if(lid[x.term]===undefined)lid[x.term]=x.id;else if(lid[x.term]!==x.id)dobles++}};
  const r=(()=>{let s=seed*7919;return()=>{s=(s*1103515245+12345)&0x7fffffff;return s/0x7fffffff}})();
  let primero=null;
  for(let t=0;t<6000;t++){ c.tick(); chequear();
    if(primero===null&&c.lider())primero=c.t;
    if(t%200===150){ const e=r();
      if(e<.3){const v=Math.floor(r()*5);if(c.nodos[v].vivo)c.caer(v)}
      else if(e<.55){const v=c.nodos.findIndex(x=>!x.vivo);if(v>=0)c.volver(v)}
      else if(e<.7){const a=Math.floor(r()*5);c.cortar([a],[0,1,2,3,4].filter(i=>i!==a))}
      else if(e<.85)c.sanar();
      if(c.lider())c.pedir('cmd'+(n++)) }
    if(c.nodos.filter(x=>!x.vivo).length>2){const v=c.nodos.findIndex(x=>!x.vivo);c.volver(v)}
  }
  tiempos.push(primero);
  // seguridad: todo lo confirmado por cualquiera coincide con lo de los demás
  const A=c.nodos; for(const a of A)for(const b of A){const k=Math.min(a.commit,b.commit);
    for(let i=0;i<k;i++)if(a.reg[i].term!==b.reg[i].term||a.reg[i].cmd!==b.reg[i].cmd)viol++}
  if(Math.max(...A.map(x=>x.term))>1)term2++;
}
tiempos.sort((a,b)=>a-b);
console.log({corridas:300,dosLideresMismoTerm:dobles,entradasConfirmadasDistintas:viol,primerLiderMediana:tiempos[150],primerLiderMax:tiempos[299]});
